from itertools import permutations
import bisect
class Solution:
    def specialPalindrome(self, n):
        specials = set()
        for mask in range(1, 1 << 9):
            sel = [d + 1 for d in range(9) if (mask >> d) & 1]
            total = sum(sel)
            if total > 17:
                continue
            odd_digits = [d for d in sel if d % 2 == 1]
            if total % 2 == 1:
                if len(odd_digits) != 1:
                    continue
                mid = odd_digits[0]
            else:
                if odd_digits:
                    continue
                mid = -1
            half = []
            for d in sel:
                half.extend([d] * (d // 2))
            for p in set(permutations(half)):
                h = ''.join(map(str, p))
                core = h + (str(mid) if mid != -1 else '') + h[::-1]
                specials.add(int(core))
        arr = sorted(specials)
        return arr[bisect.bisect_right(arr, n)]

