class Solution {
public:
    long long specialPalindrome(long long n) {
        set<long long> specials;
        for (int mask = 1; mask < (1 << 9); mask++) {
            vector<int> sel;
            int total = 0;
            for (int d = 1; d <= 9; d++) if (mask >> (d - 1) & 1) { sel.push_back(d); total += d; }
            if (total > 17) continue;
            int odds = 0, mid = -1;
            for (int d : sel) if (d % 2) { odds++; mid = d; }
            if (total % 2 == 1 && odds != 1) continue;
            if (total % 2 == 0 && odds != 0) continue;
            string half;
            for (int d : sel) half.append(d / 2, '0' + d);
            sort(half.begin(), half.end());
            do {
                string core = half;
                if (mid != -1) core += ('0' + mid);
                string rev(half.rbegin(), half.rend());
                core += rev;
                specials.insert(stoll(core));
            } while (next_permutation(half.begin(), half.end()));
        }
        auto it = specials.upper_bound(n);
        return *it;
    }
};

