class Solution {
    public long specialPalindrome(long n) {
        TreeSet<Long> specials = new TreeSet<>();
        for (int mask = 1; mask < (1 << 9); mask++) {
            List<Integer> sel = new ArrayList<>();
            int total = 0;
            for (int d = 1; d <= 9; d++) if ((mask >> (d - 1) & 1) == 1) { sel.add(d); total += d; }
            if (total > 17) continue;
            int odds = 0, mid = -1;
            for (int d : sel) if (d % 2 == 1) { odds++; mid = d; }
            if (total % 2 == 1 && odds != 1) continue;
            if (total % 2 == 0 && odds != 0) continue;
            StringBuilder hb = new StringBuilder();
            for (int d : sel) for (int t = 0; t < d / 2; t++) hb.append((char) ('0' + d));
            char[] half = hb.toString().toCharArray();
            Arrays.sort(half);
            do {
                StringBuilder sb = new StringBuilder(new String(half));
                if (mid != -1) sb.append((char) ('0' + mid));
                sb.append(new StringBuilder(new String(half)).reverse());
                specials.add(Long.parseLong(sb.toString()));
            } while (nextPerm(half));
        }
        return specials.higher(n);
    }

    private boolean nextPerm(char[] a) {
        int i = a.length - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;
        if (i < 0) return false;
        int j = a.length - 1;
        while (a[j] <= a[i]) j--;
        char t = a[i]; a[i] = a[j]; a[j] = t;
        for (int l = i + 1, r = a.length - 1; l < r; l++, r--) { t = a[l]; a[l] = a[r]; a[r] = t; }
        return true;
    }
}

