var specialPalindrome = function(n) {
    const specials = new Set();
    for (let mask = 1; mask < (1 << 9); mask++) {
        const sel = [];
        let total = 0;
        for (let d = 1; d <= 9; d++) if ((mask >> (d - 1)) & 1) { sel.push(d); total += d; }
        if (total > 17) continue;
        let odds = 0, mid = -1;
        for (const d of sel) if (d % 2 === 1) { odds++; mid = d; }
        if (total % 2 === 1 && odds !== 1) continue;
        if (total % 2 === 0 && odds !== 0) continue;
        const half = [];
        for (const d of sel) for (let t = 0; t < (d >> 1); t++) half.push(d);
        const seen = new Set();
        const permute = (arr, cur) => {
            if (!arr.length) {
                const key = cur.join(',');
                if (seen.has(key)) return;
                seen.add(key);
                const h = cur.join('');
                specials.add(BigInt(h + (mid !== -1 ? String(mid) : '') + [...h].reverse().join('')));
                return;
            }
            for (let i = 0; i < arr.length; i++)
                permute([...arr.slice(0, i), ...arr.slice(i + 1)], [...cur, arr[i]]);
        };
        permute(half, []);
    }
    const arr = [...specials].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    for (const v of arr) if (v > BigInt(n)) return Number(v);
};
